def main():
 p=argparse.ArgumentParser();p.add_argument('--config',type=Path,required=True);p.add_argument('--runs-root',type=Path,required=True);p.add_argument('--run-id',required=True);a=p.parse_args();c=yaml.safe_load(a.config.read_text());d=a.runs_root/'worldsim_v67'/c['task_id']/a.run_id;d.mkdir(parents=True,exist_ok=False);(d/'resolved.yaml').write_text(yaml.safe_dump(c,sort_keys=False));started=time.monotonic();torch.cuda.reset_peak_memory_stats();ens=torch.load(a.runs_root/c['frozen_p126']['run']/c['frozen_p126']['artifact'],map_location='cuda');members=[]
 for state in ens['member_state_dicts']:
  member=DirectionalActorGaussian(20,ens['hidden_dimensions']).cuda();member.load_state_dict(state);members.append(member.eval())
 marginal_density,fd=_load_density(a.runs_root/c['frozen_p182']['run']/c['frozen_p182']['artifact']);p199=torch.load(a.runs_root/c['frozen_p199']['run']/c['frozen_p199']['artifact'],map_location='cuda');copula=JointHorizonCopula(8,p199['hidden_dimensions'],4).cuda();copula.load_state_dict(p199['model_state_dict']);copula.eval();p215=torch.load(a.runs_root/c['frozen_p215']['run']/c['frozen_p215']['artifact'],map_location='cuda');model=PrefixSurvivalDensity(int(p215['component_count']),int(p215['token_dimension']),p215['head_dimensions']).cuda();model.load_state_dict(p215['model_state_dict']);model.eval()
 with np.load(a.runs_root/c['frozen_rows']['run']/c['frozen_rows']['artifact'],allow_pickle=False) as loaded:arrays={n:loaded[n] for n in loaded.files}
 h=np.asarray(c['horizons_seconds'],np.float32);scores,clearances,costs,scenes=_align(_trajectory_payload(arrays,members,ens,float(c['boundary_state_cost']['clearance_floor_m'])),h);raw_tokens=np.stack((scores,clearances,np.broadcast_to(h[None],scores.shape)),2);tokens=torch.from_numpy(((raw_tokens-np.asarray(p215['token_mean']))/np.asarray(p215['token_scale'])).astype(np.float32)).cuda();masks=torch.tril(torch.ones((4,4),dtype=torch.bool,device='cuda'));flat=tokens[:,None].expand(-1,4,-1,-1).reshape(-1,4,3);flat_masks=masks[None].expand(len(tokens),-1,-1).reshape(-1,4);budgets=np.asarray(c['reliability_budgets'],np.float32);raw_candidate=torch.from_numpy(_cdf(model,flat,flat_masks,budgets).reshape(len(tokens),4,-1)).cuda().clamp(1e-5,1-1e-5);aa=functional.softplus(p215['beta_raw_a'].cuda());bb=functional.softplus(p215['beta_raw_b'].cuda());bias=p215['beta_prefix_bias'].cuda();candidate=torch.sigmoid(aa*torch.log(raw_candidate)-bb*torch.log1p(-raw_candidate)+bias[None,:,None]).cpu().numpy();norms=tuple(fd['norms']);marginal=np.stack([_predict_cdf(marginal_density,scores[:,i],np.full(len(scores),h[i],np.float32),clearances[:,i],budgets,norms) for i in range(4)],1);raw=np.concatenate((scores,clearances),1);features=torch.from_numpy(((raw-np.asarray(p199['feature_mean']))/np.asarray(p199['feature_scale'])).astype(np.float32)).cuda();baseline=_prefix_copula_probabilities(copula,features,torch.from_numpy(marginal.astype(np.float32)).cuda(),int(c['evaluation']['monte_carlo_samples']),int(c['evaluation']['seed']));truth=np.maximum.accumulate(costs,1)[:,:,None]<=budgets[None,None,:];cb=float(np.mean((candidate-truth)**2));pb=float(np.mean((baseline-truth)**2));ce=float(np.mean(np.abs(candidate.mean(0)-truth.mean(0))));pe=float(np.mean(np.abs(baseline.mean(0)-truth.mean(0))));br=(pb-cb)/pb;cr=(pe-ce)/max(pe,1e-12);checks={'macro_prefix_integrated_Brier_strictly_better_than_P199':cb<pb,'macro_prefix_calibration_error_noninferior_to_P199':cr>=float(c['decision']['minimum_macro_calibration_error_reduction_vs_P199'])};verdict=c['verdict_on_pass'] if all(checks.values()) else c['verdict_on_failure'];summary={'schema_version':c['output_schema_version'],'task_id':c['task_id'],'hypothesis_id':c['hypothesis_id'],'status':'done','verdict':verdict,'role':c['role'],'joint_trajectory_count':int(len(scores)),'macro_prefix_integrated_brier':cb,'P199_macro_prefix_integrated_brier':pb,'macro_Brier_reduction_vs_P199':br,'macro_prefix_calibration_error':ce,'P199_macro_prefix_calibration_error':pe,'macro_calibration_error_reduction_vs_P199':cr,'final_four_horizon_brier':float(np.mean((candidate[:,-1]-truth[:,-1])**2)),'P199_final_four_horizon_brier':float(np.mean((baseline[:,-1]-truth[:,-1])**2)),'decision_checks':checks,'resources':{'gpu':torch.cuda.get_device_name(0),'peak_gpu_memory_gib':torch.cuda.max_memory_allocated()/2**30,'peak_rss_gib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/2**20,'wall_seconds':time.monotonic()-started},'claim_boundary':c['claim_boundary']};(d/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(d/'status.json').write_text(json.dumps({'status':'done','completed_at_utc':datetime.now(timezone.utc).isoformat()},indent=2)+'\n');print(json.dumps({'run_dir':str(d),**summary},indent=2))


